// Shared bare Node VM / standalone vendored QuickJS fixture; no SDK host shims.
(function(){
 let checks=0;const scenarios=[],ok=(v,m)=>{checks++;if(!v)throw Error(m);},run=(n,f)=>{f();scenarios.push(n);},rejects=f=>{let failed=false;try{f();}catch(e){failed=true;}ok(failed,'Expected rejection');};
 nativeInit(40);const model=nativeModel,store=model.store,columns=store.columns,index=store.index,act=(a,v)=>nativeDataExploration(a,v);let notices=0;nativeAPI.invalidate=()=>notices++;
 run('off and explicit action validation',()=>{ok(!act('refresh').active,'OFF');rejects(()=>act('read'));rejects(()=>act('navigate','Enter'));});
 run('navigation and refresh compute zero',()=>{const view=JSON.stringify([model.view,model.follow,model.crosshair]),listeners=store.listeners.size,get=model.indicators.get;let calls=0;model.indicators.get=()=>{calls++;throw Error('compute');};try{ok(act('setActive',true).index===39,'Last');for(const k of ['Home','ArrowRight','End','ArrowLeft','ArrowDown','ArrowUp'])act('navigate',k);act('refresh');ok(calls===0,'No computation');ok(JSON.stringify([model.view,model.follow,model.crosshair])===view&&store.listeners.size===listeners,'Ownership');}finally{model.indicators.get=get;}});
 run('explicit read and refreshed text',()=>{act('navigate','End');const r=act('read');ok(r.phase==='read'&&r.text.includes('Current plotted values, cutoff 39')&&r.text.length<=4096,'Read');const b=store.at(39);store.update(39,{...b,volume:b.volume+1});const s=act('refresh');ok(s.time===r.time&&!s.text.includes('Current plotted values'),'Refresh');});
 run('unchanged receipt preserves owner and version',()=>{const v=store.version,n=notices,r=nativeApplyUnchangedDataEvents([{kind:'update',bar:store.at(39)}]);ok(r.schema==='aster.native-data-batch'&&r.unchanged===true&&r.receipt.unchanged===true,'Receipt');ok(store.version===v&&r.beforeVersion===v&&r.afterVersion===v&&store.columns===columns&&store.index===index&&notices===n,'Unchanged');});
 run('changed volume replaces and notifies once',()=>{const v=store.version,n=notices,r=nativeApplyUnchangedDataEvents([{kind:'update',bar:{...store.at(39),volume:17}}]);ok(!r.unchanged&&store.version===v+1&&store.at(39).volume===17&&notices===n+1,'Replace');});
 run('whole batch validates before unchanged admission',()=>{const b=store.at(39),v=store.version,n=notices;rejects(()=>nativeApplyUnchangedDataEvents([{kind:'update',bar:{...b,high:b.low-1}},{kind:'update',bar:b}]));ok(store.version===v&&store.at(39).volume===b.volume&&notices===n,'Atomic');ok(nativeApplyUnchangedDataEvents([{kind:'update',bar:{...b,volume:18}},{kind:'update',bar:b}]).unchanged&&store.version===v,'Final equality');});
 run('signed zero remains distinct',()=>{const b=store.at(39);nativeApplyUnchangedDataEvents([{kind:'update',bar:{...b,volume:0}}]);ok(!nativeApplyUnchangedDataEvents([{kind:'update',bar:{...b,volume:-0}}]).unchanged&&Object.is(store.at(39).volume,-0),'Signed zero');ok(nativeApplyUnchangedDataEvents([{kind:'update',bar:store.at(39)}]).unchanged,'Repeated zero');});
 run('append anchor and legacy publication',()=>{const s=act('refresh'),b=store.at(39);ok(!nativeApplyUnchangedDataEvents([{kind:'append',bar:{...b,time:b.time+60000}}]).unchanged&&store.length===41,'Append');ok(act('refresh').time===s.time&&act('refresh').index===39,'Anchor');const v=store.version;nativeCommand('applyDataEvents',[[{kind:'update',bar:store.at(40)}]]);ok(store.version===v+1,'Legacy');});
 run('gesture rejection preserves off state',()=>{act('setActive',false);nativeInput.gesture={kind:'pan'};rejects(()=>act('setActive',true));ok(!act('refresh').active&&nativeInput.gesture.kind==='pan','Gesture');nativeInput.gesture=null;});
 run('cleanup preserves borrowed buffers',()=>{model.dispose();ok(store.listeners.size===0&&model.indicators.entries.size===0&&columns.close.buffer.byteLength>0,'Cleanup');rejects(()=>act('refresh'));});
 return JSON.stringify({case:'native-controls-quickjs',passed:true,checks,scenarios});
})();
